@Composable
fun NsoCoatOfArmsTwoToneIcon(
    modifier: Modifier = Modifier.size(20.dp),
    primaryColor: Color = MaterialTheme.colorScheme.primary,
    secondaryColor: Color = MaterialTheme.colorScheme.primary.copy(alpha = 0.40f),
    detailColor: Color = MaterialTheme.colorScheme.surfaceContainerHigh
) {
    val pathRiver = remember { PathParser().parsePathString(COAT_RIVER).toPath() }
    val pathSolidFill = remember { PathParser().parsePathString(COAT_SOLID_FILL).toPath() }
    val pathSolidStroke = remember { PathParser().parsePathString(COAT_SOLID_STROKE).toPath() }
    val pathDetails = remember { PathParser().parsePathString(COAT_DETAILS).toPath() }

    Canvas(modifier = modifier) {
        val scaleFactor = size.minDimension / 331.84f
        val dx = (size.width - 272.49f * scaleFactor) / 2f
        val dy = (size.height - 331.84f * scaleFactor) / 2f

        translate(left = dx, top = dy) {
            scale(scaleFactor, scaleFactor, pivot = Offset.Zero) {
                // 1. Центральный лазоревый столб (Обь) в мягком акцентном тоне
                drawPath(pathRiver, secondaryColor)
                // 2. Силуэты соболей, каравая и элементов щита в плотном акцентном цвете
                drawPath(pathSolidFill, primaryColor)
                drawPath(pathSolidStroke, primaryColor, style = Stroke(width = 1.6f))
                // 3. Анатомические вырезы (когти, глаза, зубы) под тон подложки
                drawPath(pathDetails, detailColor)
            }
        }
    }
}
